// Automations -> Schedules tab + editor drawer, AS GRAPH SOURCE (#3642, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app real modules (the shared/ui
// design system + the store via appModules, the mcp/scheduler surface via the automations graph-platform,
// and the sibling tab bodies as @/components/* graph records). Behaviour runs here -- no forked render path.
// Preview note: the scheduler/cron/format libs and the store read/mutators are app-internal
// (unresolvable in this sandbox) -- inlined locally below, with `automations`/`tabs`/mutators promoted
// to props (defaulting to sample data) so AutomationsWorkspace can own the real state.

import { Pane } from "@/shared/ui/overlay/Pane";
import { Chip } from "@/shared/ui/data/Chip";
import { SegmentedControl } from "@/shared/ui/controls/SegmentedControl";
import { TextField, SelectField } from "@/shared/ui/controls/Field";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Grid } from "@/shared/ui/layout/Grid";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

type Every = "minute" | "hour" | "day" | "weekday";
type RunStatus = "ok" | "skipped" | "fail";
interface Run { at: number; status: RunStatus; note: string }
type When = { kind: "simple"; every: Every; at: string } | { kind: "cron"; expr: string };
interface Automation {
  id: string; name: string; armed: boolean; when: When; action: string; command?: string;
  targetTab?: string; targetPaneIdx: number; runs: Run[]; nextRunAt?: number; lastRunAt?: number;
}
interface TabInfo { name: string; panes: number }

const EVERY_OPTS: Every[] = ["minute", "hour", "day", "weekday"];

function isValidCron(expr: string): boolean {
  return expr.trim().split(/\s+/).length === 5;
}
function fmtStamp(ts: number): string {
  return new Date(ts).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

const NOW = 1700000000000;
const SAMPLE_TABS: TabInfo[] = [{ name: "design-studio", panes: 2 }, { name: "infra", panes: 1 }];
const SAMPLE_AUTOMATIONS: Automation[] = [
  { id: "a1", name: "Nightly build", armed: true, action: "command", command: "cargo build --release",
    when: { kind: "simple", every: "day", at: "02:00" }, targetTab: "design-studio", targetPaneIdx: 0,
    nextRunAt: NOW + 3600000, lastRunAt: NOW - 82800000,
    runs: [{ at: NOW - 82800000, status: "ok", note: "exit 0" }, { at: NOW - 169200000, status: "fail", note: "exit 1" }] },
  { id: "a2", name: "Deploy check", armed: false, action: "command", command: "npm run deploy:check",
    when: { kind: "cron", expr: "0 9 * * 1" }, targetTab: "infra", targetPaneIdx: 0,
    lastRunAt: NOW - 604800000, runs: [{ at: NOW - 604800000, status: "skipped", note: "target pane not open" }] },
];

function runsTable(runs: Run[]) {
  if (runs.length === 0) {
    return (
      <Box className="mono" pad={14} radius={6} style={{ textAlign: "center", color: "var(--fg-dim)", fontSize: 11, border: "1px dashed var(--border)" }}>
        no runs yet
      </Box>
    );
  }
  const color = (s: RunStatus) => (s === "ok" ? "var(--success)" : s === "fail" ? "var(--danger)" : "var(--fg-dim)");
  return (
    <Stack gap={1} style={{ border: "1px solid var(--border-soft)", borderRadius: 6, overflow: "hidden" }}>
      {runs.map((r, i) => (
        <Row key={i} align="center" gap={10} wrap style={{ padding: "7px 10px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
          <Text as="span" mono size={10.5} tone="dim">{fmtStamp(r.at)}</Text>
          <Text as="span" mono size={10.5} style={{ color: color(r.status) }}>{r.status === "ok" ? "check ok" : r.status === "skipped" ? "- skipped" : "x fail"}</Text>
          <Text as="span" tone="muted" style={{ flex: 1, minWidth: 0 }}>{r.note}</Text>
        </Row>
      ))}
    </Stack>
  );
}

const noop = () => {};

/** The Schedules tab -- the full-width list of automations. Selecting one opens the slide-in
 *  <ScheduleDrawer> (rendered in the screen overlay), matching the MCP + Skills editor drawers (#1824). */
export function SchedulesTab({
  automations = SAMPLE_AUTOMATIONS, selectedId = null, onSelect = noop, onNew = noop,
}: {
  automations?: Automation[]; selectedId?: string | null; onSelect?: (id: string) => void; onNew?: () => void;
}) {
  if (automations.length === 0) {
    return (
      <EmptyState
        title="No automations yet"
        description="Schedule a command to fire into a console pane on a cadence."
        actions={<Button variant="primary" onClick={onNew}>+ New automation</Button>}
      />
    );
  }

  const armedCount = automations.filter((a) => a.armed).length;
  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Card style={{ padding: 0 }}>
        <Box style={{ padding: "10px 12px", borderBottom: "1px solid var(--border-soft)" }}>
          <Row align="baseline" gap={8} wrap>
            <Text as="h3" weight={600} size={13} style={{ margin: 0 }}>Schedules</Text>
            <Text as="span" className="hint" size={10}>{automations.length} total - {armedCount} armed</Text>
          </Row>
        </Box>
        <Box style={{ padding: 8 }}>
          {automations.map((a) => {
            const on = a.id === selectedId;
            return (
              <Box key={a.id} onClick={() => onSelect(a.id)} style={{
                padding: "10px 12px", borderRadius: 7, cursor: "pointer", marginBottom: 4,
                background: on ? "var(--bg-elev2)" : "transparent", border: on ? "1px solid var(--accent)" : "1px solid transparent",
              }}>
                <Row align="center" gap={8}>
                  <Box as="span" bg={a.armed ? "var(--success)" : "var(--fg-dim)"} radius={99} style={{ width: 7, height: 7 }} />
                  <Box style={{ flex: 1 }} />
                  <Chip style={{ fontSize: 9.5 }}>{a.action}</Chip>
                </Row>
                <Text as="div" weight={600} size={12} style={{ marginTop: 4 }}>{a.name}</Text>
                <Row gap={10} wrap className="mono" style={{ marginTop: 3, fontSize: 10, color: "var(--fg-muted)" }}>
                  <Text as="span">{a.when.kind === "simple"
                    ? `every ${a.when.every}${a.when.every !== "minute" ? " - " + a.when.at : ""}`
                    : `cron - ${a.when.expr}`}</Text>
                  <Text as="span">{a.targetTab ? `-> ${a.targetTab} - pane ${a.targetPaneIdx + 1}` : "-> (no target)"}</Text>
                </Row>
              </Box>
            );
          })}
          <Box pad={[12, 8]}>
            <Button variant="ghost" style={{ width: "100%", justifyContent: "center" }} onClick={onNew}>+ new automation</Button>
          </Box>
        </Box>
      </Card>
    </Box>
  );
}

/** The slide-in editor for the selected schedule -- the unified <Pane> drawer (#1824), the same
 *  chrome as the MCP server/hook + Skills drawers. Rendered in the AutomationsWorkspace overlay. */
export function ScheduleDrawer({
  selected = SAMPLE_AUTOMATIONS[0], onClose = noop, onViewAllHistory = noop,
  onUpdate = noop, onSetArmed = noop, onRemove = noop, tabs = SAMPLE_TABS, paneNameFor = () => undefined,
}: {
  selected?: Automation | null;
  onClose?: () => void;
  onViewAllHistory?: (id: string) => void;
  onUpdate?: (id: string, patch: Partial<Automation>) => void;
  onSetArmed?: (id: string, armed: boolean) => void;
  onRemove?: (id: string) => void;
  tabs?: TabInfo[];
  paneNameFor?: (tabName: string, paneIdx: number) => string | undefined;
}) {
  const sel = selected;

  const tabInfo = sel ? tabs.find((t) => t.name === sel.targetTab) : undefined;
  const paneOpts = tabInfo ? Array.from({ length: tabInfo.panes }, (_, i) => i) : [];
  const patchSimple = (p: Partial<Extract<When, { kind: "simple" }>>) => {
    if (sel && sel.when.kind === "simple") onUpdate(sel.id, { when: { ...sel.when, ...p } });
  };
  const setMode = (kind: "simple" | "cron") => {
    if (!sel || kind === sel.when.kind) return;
    onUpdate(sel.id, {
      when: kind === "cron" ? { kind: "cron", expr: "0 9 * * *" } : { kind: "simple", every: "day", at: "09:00" },
    });
  };
  const esLabel = (color: string, label: string) => (
    <Text as="span" mono size={10} weight={600} style={{ color, textTransform: "uppercase", letterSpacing: ".05em", width: 70, flexShrink: 0 }}>{label}</Text>
  );

  return (
    <Pane
      flush
      open={!!sel}
      onClose={onClose}
      onRemove={() => { if (sel) { onRemove(sel.id); onClose(); } }}
      header={sel && (
        <Row align="center" gap={10} wrap style={{ flex: 1 }}>
          {/* eslint-disable-next-line no-restricted-syntax -- bespoke Pane-header title input, not a .field stack; TextField would change the header chrome */}
          <input value={sel.name} onChange={(e) => onUpdate(sel.id, { name: e.target.value })} style={{ background: "transparent", border: 0, font: "inherit", fontWeight: 600, fontSize: 13, color: "var(--fg)", flex: 1, minWidth: 0 }} />
          <Box as="span" onClick={() => onSetArmed(sel.id, !sel.armed)} title="armed" style={{ width: 30, height: 17, borderRadius: 99, cursor: "pointer", background: sel.armed ? "var(--success)" : "var(--bg-elev2)", position: "relative", flexShrink: 0 }}>
            <Box as="span" style={{ position: "absolute", top: 2, left: sel.armed ? 15 : 2, width: 13, height: 13, borderRadius: 99, background: "#fff" }} />
          </Box>
          <Text as="span" mono size={11} style={{ color: sel.armed ? "var(--success)" : "var(--fg-dim)" }}>{sel.armed ? "armed" : "disarmed"}</Text>
        </Row>
      )}
      body={sel && (
        <Stack gap={14}>
          {/* when */}
          <Row align="start" gap={12} wrap>
            {esLabel("var(--accent)", "when")}
            <Stack gap={8} style={{ flex: 1, minWidth: 200 }}>
              <SegmentedControl
                options={[
                  { label: "simple", on: sel.when.kind === "simple", onClick: () => setMode("simple") },
                  { label: "cron", on: sel.when.kind === "cron", onClick: () => setMode("cron") },
                ]}
              />
              {sel.when.kind === "simple" ? (
                <Row gap={8} wrap className="mono" style={{ fontSize: 11, color: "var(--fg-muted)" }} align="center">
                  <Text as="span">every</Text>
                  <SelectField style={{ width: 110 }} value={sel.when.every} onChange={(v) => patchSimple({ every: v as Every })}>
                    {EVERY_OPTS.map((o) => <option key={o} value={o}>{o}</option>)}
                  </SelectField>
                  {sel.when.every !== "minute" && (
                    <>
                      <Text as="span">at</Text>
                      <TextField style={{ width: 90 }} value={sel.when.at}
                        placeholder={sel.when.every === "hour" ? ":MM" : "HH:MM"}
                        onChange={(v) => patchSimple({ at: v })} />
                    </>
                  )}
                </Row>
              ) : (
                <Row gap={8} wrap className="mono" style={{ fontSize: 11, color: "var(--fg-muted)" }} align="center">
                  <Text as="span">cron</Text>
                  <TextField style={{ width: 160 }} value={sel.when.expr} placeholder="0 9 * * *" spellCheck={false}
                    onChange={(v) => onUpdate(sel.id, { when: { kind: "cron", expr: v } })} />
                  {isValidCron(sel.when.expr)
                    ? <Text as="span" tone="dim" size={10}>min hour dom month dow</Text>
                    : <Text as="span" tone="danger" size={10}>invalid expression</Text>}
                </Row>
              )}
              <Row align="center" gap={10} wrap style={{ padding: "7px 10px", background: "var(--bg-elev)", borderRadius: 6 }}>
                <Text as="span" mono size={10} tone="dim">next run</Text>
                <Text as="span" mono size={10.5}>{sel.armed ? fmtStamp(sel.nextRunAt ?? Date.now()) : "disarmed"}</Text>
                <Box style={{ flex: 1 }} />
                <Text as="span" mono size={10} tone="dim">last - {sel.lastRunAt ? fmtStamp(sel.lastRunAt) : "never"}</Text>
              </Row>
            </Stack>
          </Row>

          {/* target */}
          <Row align="start" gap={12} wrap>
            {esLabel("var(--info)", "target")}
            <Box style={{ flex: 1, minWidth: 200 }}>
              {tabs.length === 0 ? (
                <Text as="span" className="hint">No console tabs open -- open a console (and a pane) to target.</Text>
              ) : (
                <Grid cols={2} gap={10}>
                  <SelectField label="console" value={sel.targetTab ?? ""} onChange={(v) => onUpdate(sel.id, { targetTab: v, targetPaneIdx: 0 })}>
                    {!tabs.some((t) => t.name === sel.targetTab) && <option value={sel.targetTab}>{sel.targetTab || "(pick a console)"}</option>}
                    {tabs.map((t) => <option key={t.name} value={t.name}>{t.name}</option>)}
                  </SelectField>
                  <SelectField label="pane" value={String(sel.targetPaneIdx)} onChange={(v) => onUpdate(sel.id, { targetPaneIdx: Number(v) })}>
                    {paneOpts.length === 0 && <option value={0}>Pane 1</option>}
                    {paneOpts.map((i) => {
                      const nm = sel.targetTab ? paneNameFor(sel.targetTab, i) : undefined;
                      return <option key={i} value={i}>Pane {i + 1}{nm ? ` - ${nm}` : ""}</option>;
                    })}
                  </SelectField>
                </Grid>
              )}
            </Box>
          </Row>

          {/* action */}
          <Row align="start" gap={12} wrap>
            {esLabel("var(--success)", "action")}
            <Stack gap={8} style={{ flex: 1, minWidth: 200 }}>
              <TextField placeholder="command to run in the target pane..." value={sel.command ?? ""} onChange={(v) => onUpdate(sel.id, { command: v })} />
              <Text as="span" className="hint">Typed into the target pane session, then submitted.</Text>
            </Stack>
          </Row>

          {/* history */}
          <Row align="start" gap={12} wrap style={{ paddingTop: 10, borderTop: "1px solid var(--border-soft)" }}>
            {esLabel("var(--fg-dim)", "history")}
            <Box style={{ flex: 1, minWidth: 200 }}>
              <Row align="baseline" gap={10} style={{ marginBottom: 10 }}>
                <Text as="span" mono size={11} tone="muted">last {sel.runs.length} runs</Text>
                <Box as="span" style={{ flex: 1 }} />
                {sel.runs.length > 0 && <Button variant="ghost" style={{ height: 22, fontSize: 10.5 }} onClick={() => onViewAllHistory(sel.id)}>view all -&gt;</Button>}
              </Row>
              {runsTable(sel.runs)}
            </Box>
          </Row>
        </Stack>
      )}
    />
  );
}
